<?php
namespace App\Http\Controllers\Auth;use App\Http\Controllers\Controller;use App\Models\{SecurityLoginHistory,User};use Illuminate\Http\Request;use Illuminate\Support\Facades\{Auth,Cache,Mail};use Illuminate\Support\Str;use Inertia\Inertia;
class TwoFactorChallengeController extends Controller{public function show(Request$r){abort_unless($r->session()->has('two_factor_user_id'),403);return Inertia::render('Auth/TwoFactorChallenge');}public function verify(Request$r){$d=$r->validate(['code'=>'required|digits:6']);$id=$r->session()->get('two_factor_user_id');abort_unless($id&&hash_equals((string)Cache::pull('login-2fa:'.$id),hash('sha256',$d['code'])),422,'Invalid or expired verification code.');$user=User::findOrFail($id);Auth::login($user,$r->session()->pull('two_factor_remember',false));$r->session()->forget('two_factor_user_id');$r->session()->regenerate();SecurityLoginHistory::create(['user_id'=>$user->id,'ip_address'=>$r->ip(),'user_agent'=>Str::limit((string)$r->userAgent(),65535,''),'device_type'=>'Two-factor verified','login_at'=>now()]);return redirect()->intended(route('dashboard',absolute:false));}public static function send(User$user):void{$code=(string)random_int(100000,999999);Cache::put('login-2fa:'.$user->id,hash('sha256',$code),now()->addMinutes(5));Mail::raw("Your ERP verification code is {$code}. It expires in 5 minutes.",fn($m)=>$m->to($user->email)->subject('Login verification code'));}}
